// Generated by Cypress Author on 2026-11-02.
// Exam evidence uses the real UI, real HTTP responses and a guarded synthetic DB.
const evidence = [];

function capture(ordinal, role, step, action, outcome, selector = null) {
  const name = `${String(ordinal).padStart(2, '0')}-${role.toLowerCase()}-${step}`;
  cy.window().then((win) => {
    const target = selector ? win.document.querySelector(selector) : null;
    const offset = step === 'new-barber-services-hours' ? 0 : 100;
    const top = target ? target.getBoundingClientRect().top + win.scrollY - offset : 0;
    // Native instant scrolling bypasses the site's CSS smooth-scroll animation.
    win.scrollTo({ top: Math.max(0, top), behavior: 'instant' });
  });
  cy.waitForScroll();
  // Crop the actual visible form column, keeping viewport context for wide pages.
  // This is a native browser capture, with no resizing or fabricated UI.
  cy.get('body').then(($body) => {
    const panel = $body.find('.details-panel')[0];
    const options = { capture: 'viewport', overwrite: true };
    if (step.includes('schedule')) {
      // Matching colleague cards show the owner's access and barber privacy clearly.
      cy.get('section.schedule-section').eq(1).then(($section) => {
        const rect = $section[0].getBoundingClientRect();
        cy.screenshot(name, { capture: 'viewport', overwrite: true,
          clip: { x: Math.floor(rect.left), y: Math.floor(rect.top),
            width: Math.ceil(rect.width), height: Math.ceil(rect.height) } });
      });
      return;
    }
    if (panel) {
      const rect = panel.getBoundingClientRect();
      options.clip = { x: Math.floor(rect.left), y: 0, width: Math.ceil(rect.width), height: 800 };
    }
    cy.screenshot(name, options);
  });
  cy.then(() => evidence.push({ ordinal, role, step_title: step.replaceAll('-', ' '), action,
    expected_outcome: outcome, actual_outcome: outcome, filename: `${name}.png` }));
}

function staffEntry(role, username, first) {
  cy.visit('/?lang=en');
  cy.get('html').should('have.attr', 'lang', 'en');
  capture(first, role, 'home-staff-entry', 'Open the homepage and scroll to its footer.',
    'The public homepage exposes the Staff sign in link.', 'footer');
  cy.contains('footer a', 'Staff sign in').click();
  cy.location('pathname').should('eq', '/staff/login/');
  cy.get('[name="username"]').type(username);
  cy.env(['auditPassword']).then(({ auditPassword }) => {
    cy.get('[name="password"]').type(auditPassword, { log: false }).should('have.attr', 'type', 'password');
  });
  capture(first + 1, role, 'login-form', 'Enter the synthetic staff username and masked password.',
    'The sign-in form is ready to submit.');
  cy.contains('main button', 'Sign in').click();
  cy.location('pathname').should('eq', '/staff/');
  cy.contains('main', role === 'OWNER' ? 'SHOP OWNER' : 'YOUR WORKSPACE').should('be.visible');
  capture(first + 2, role, 'dashboard', 'Submit Sign in.', 'The correct role dashboard is displayed.');
}

function dashboard() {
  cy.contains('header a', 'Dashboard').click();
  cy.location('pathname').should('eq', '/staff/');
}

function schedule(seed, role, ordinal) {
  cy.contains('a', 'Barbers schedules').click();
  cy.get('[name="date"]').clear().type(seed.date);
  cy.get('#barber-filter').select('');
  cy.get('#view-filter').select('day');
  cy.contains('main button', 'Show').click();
  cy.contains('Demo Daniel').should('be.visible');
  if (role === 'OWNER') {
    cy.contains('Demo Martin').should('be.visible');
    cy.get('a[href="tel:+359888000002"]').should('exist');
  } else {
    cy.get('main').should('not.contain', 'Demo Martin').and('not.contain', '+359888000002').and('not.contain', 'boris@example.invalid');
    cy.get(`form[action="/staff/appointments/${seed.appointments.boris.id}/cancel/"]`).should('not.exist');
    cy.contains('Booked').should('be.visible');
  }
  capture(ordinal, role, role === 'OWNER' ? 'team-schedule' : 'colleague-schedule-privacy',
    'Open Barbers schedules, choose 17 November 2026, all barbers and day view, then Show.',
    role === 'OWNER' ? 'The owner sees both synthetic appointments and their contact details.' :
      'The barber sees their own customer details; the colleague reservation says Booked with no customer contacts.',
    'section.schedule-section:nth-of-type(2)');
}

function hoursAndDaysOff(seed, role, first) {
  cy.get(`a[href="/staff/barbers/${seed.barbers.alan}/hours/"]`).click();
  cy.get('[name="start_0"]').clear().type('10:00');
  capture(first, role, 'weekly-hours-edit', 'Change Monday opening time from 09:00 to 10:00.',
    'The weekly-hours form contains the new opening time.', '[name="open_0"]');
  cy.contains('button', 'Save weekly hours').click();
  cy.contains('Schedule saved.').should('be.visible');
  cy.get('[name="start_0"]').should('have.value', '10:00');
  cy.task('db:snapshot').then((state) => {
    expect(state.hours.find((row) => row.barber_id === seed.barbers.alan && row.weekday === 0).opens_at).to.equal('10:00:00');
  });
  capture(first + 1, role, 'weekly-hours-saved', 'Save weekly hours.',
    'Schedule saved is visible and the database stores Monday 10:00 opening.');
  cy.get('[name="date"]').type('2026-11-23');
  cy.get('[name="end_date"]').type('2026-11-25');
  capture(first + 2, role, 'days-off-range', 'Enter 23–25 November 2026 as the day-off range.',
    'Both inclusive range endpoints are visible.', '[name="date"]');
  cy.contains('button', 'Add days off').click();
  cy.contains('Schedule saved.').should('be.visible');
  for (const date of ['23.11.2026', '24.11.2026', '25.11.2026']) cy.contains('li', date).should('be.visible');
  cy.task('db:snapshot').then((state) => {
    expect(state.daysOff.filter((row) => row.barber_id === seed.barbers.alan).map((row) => row.date))
      .to.deep.equal(['2026-11-23', '2026-11-24', '2026-11-25']);
    expect(state.appointments).to.have.length(2);
    expect(state.appointments.every((row) => row.cancelled_at === null)).to.equal(true);
  });
  capture(first + 3, role, 'days-off-saved', 'Add days off.',
    'The three dates are listed and stored; existing appointments remain unchanged.', '[name="date"]');
}

describe('Exam walkthrough: successful OWNER → BARBER → CLIENT journeys', () => {
  beforeEach(() => {
    cy.viewport(1200, 800);
    cy.task('db:examPresentation');
  });
  after(() => cy.writeFile('.artifacts/cypress/exam-evidence-metadata.json', evidence));

  it('OWNER: sign in, create barber, view schedule, edit service and save working hours and days off', () => {
    staffEntry('OWNER', 'owner', 1);
    cy.get('@seed').then((seed) => {
      cy.contains('a', 'Add barber').click();
      cy.get('[name="username"]').type('demo_nikolay');
      cy.get('[name="name"]').type('Demo Nikolay');
      cy.env(['auditPassword']).then(({ auditPassword }) => {
        cy.get('[name="password"]').type(auditPassword, { log: false });
        cy.get('[name="password_confirm"]').type(auditPassword, { log: false });
      });
      capture(4, 'OWNER', 'new-barber-account', 'Open Add barber and fill username, display name and password confirmation.',
        'The new synthetic barber account fields are filled; passwords stay masked.', '[name="username"]');
      cy.get(`[name="services"][value="${seed.services.cut}"]`).should('be.checked');
      cy.get(`[name="services"][value="${seed.services.beard}"]`).should('be.checked');
      cy.get('[name="open_6"]').uncheck();
      capture(5, 'OWNER', 'new-barber-services-hours', 'Keep both active services and set Sunday as closed.',
        'Initial weekly hours are visible with Sunday closed.', '.hours-rows');
      cy.contains('button', 'Save barber').click();
      cy.location('pathname').should('eq', '/staff/');
      cy.contains('Profile saved.').should('be.visible');
      cy.contains('h3', 'Demo Nikolay').should('exist');
      cy.task('db:snapshot').then((state) => {
        const user = state.users.find((row) => row.username === 'demo_nikolay');
        const barber = state.barbers.find((row) => row.user_id === user.id);
        expect(barber).to.include({ name: 'Demo Nikolay', is_active: true });
        expect(user.password).not.to.include('Synthetic-Audit');
        expect(state.hours.filter((row) => row.barber_id === barber.id)).to.have.length(6);
        expect(state.assignments.filter((row) => row.barber_id === barber.id).map((row) => row.service_id)).to.deep.equal([seed.services.cut, seed.services.beard]);
      });
      capture(6, 'OWNER', 'barber-created', 'Save barber.', 'Profile saved appears and Demo Nikolay is accepting bookings.');
      cy.contains('h3', 'Demo Nikolay').closest('article').screenshot('core-owner-created', { overwrite: true });
      schedule(seed, 'OWNER', 7);
      dashboard();
      cy.contains('a', 'Manage services').click();
      cy.contains('h2', 'Classic Haircut').should('be.visible');
      capture(8, 'OWNER', 'service-catalogue', 'Open Manage services.', 'The catalogue shows durations, prices and service-edit links.');
      cy.get(`a[href="/staff/services/${seed.services.cut}/"]`).click();
      cy.get('[name="price"]').clear().type('22.00');
      capture(9, 'OWNER', 'service-price-edit', 'Open Classic Haircut and change its price to 22.00 EUR.',
        'The service form contains the new price.', '[name="duration_minutes"]');
      cy.contains('button', 'Save service').click();
      cy.contains('Service saved.').should('be.visible');
      cy.contains('article', 'Classic Haircut').should('contain', '22.00 EUR');
      cy.task('db:snapshot').then((state) => {
        expect(state.services.find((row) => row.id === seed.services.cut).price).to.equal('22.00');
        expect(state.appointments.every((row) => row.price === '20.00')).to.equal(true);
      });
      capture(10, 'OWNER', 'service-saved', 'Save service.', 'The catalogue shows 22.00 EUR; existing bookings retain their 20.00 EUR quote.');
      dashboard();
      hoursAndDaysOff(seed, 'OWNER', 11);
    });
  });

  it('BARBER: sign in, change own services and hours, add days off and view a private colleague schedule', () => {
    staffEntry('BARBER', 'alan', 15);
    cy.get('@seed').then((seed) => {
      cy.contains('a', 'My services').click();
      cy.get(`[name="services"][value="${seed.services.inactive}"]`).uncheck();
      cy.get(`[name="services"][value="${seed.services.beard}"]`).uncheck();
      capture(18, 'BARBER', 'own-services-edit', 'Open My services and retain only Classic Haircut.',
        'Only the intended bookable service remains checked.', 'fieldset');
      cy.contains('button', 'Save services').click();
      cy.contains('Services saved.').should('be.visible');
      cy.get(`[name="services"][value="${seed.services.cut}"]`).should('be.checked');
      cy.get(`[name="services"][value="${seed.services.beard}"]`).should('not.be.checked');
      cy.task('db:snapshot').then((state) => {
        expect(state.assignments.filter((row) => row.barber_id === seed.barbers.alan).map((row) => row.service_id)).to.deep.equal([seed.services.cut]);
        expect(state.appointments).to.have.length(2);
      });
      capture(19, 'BARBER', 'own-services-saved', 'Save services.', 'Services saved appears and the database contains only the Classic Haircut assignment.');
      dashboard();
      hoursAndDaysOff(seed, 'BARBER', 20);
      dashboard();
      schedule(seed, 'BARBER', 24);
    });
  });

  it('CLIENT: view services, select service/barber/date/time and confirm a real successful reservation', () => {
    cy.get('@seed').then((seed) => {
      cy.task('db:snapshot').then((before) => {
        cy.visit('/?lang=en');
        cy.get('nav a[href="#services"]').click();
        cy.contains('#services', 'Classic Haircut').should('be.visible');
        capture(25, 'CLIENT', 'homepage-services', 'Open the homepage and choose Services in the navigation.',
          'The public menu displays service descriptions, durations and prices.', '#services');
        cy.get('main a[href="/book/"]').first().click();
        cy.location('pathname').should('eq', '/book/');
        capture(26, 'CLIENT', 'booking-start', 'Click the homepage Book a visit button.',
          'The booking page opens with service, barber and date choices.');
        cy.chooseFilter('service', seed.services.cut);
        capture(27, 'CLIENT', 'service-selected', 'Select Classic Haircut.',
          'The service is selected and compatible options refresh.', '#visit-selection');
        cy.chooseFilter('barber', seed.barbers.alan);
        capture(28, 'CLIENT', 'barber-selected', 'Select Demo Alan.',
          'The barber is selected and the calendar shows matching dates.', '#visit-selection');
        cy.chooseFilter('date', seed.date);
        cy.get('[data-booking-time]').contains('09:00').should('be.visible');
        capture(29, 'CLIENT', 'date-and-available-times', 'Choose 17 November 2026 in the calendar.',
          'Available appointment times are displayed for the selected service, barber and date.', '#time-selection-heading');
        cy.intercept('GET', '/book/?*').as('timeSelection');
        cy.get('[data-booking-time]').contains('09:00').click();
        cy.wait('@timeSelection').its('response.statusCode').should('eq', 200);
        cy.get('#details').should('be.visible');
        cy.get('#details [name="time"]').should('have.value', '09:00');
        capture(30, 'CLIENT', 'time-selected-contact-form', 'Choose the available 09:00 time.',
          'The contact form opens for the selected visit.', '#details');
        cy.get('#details [name="customer_name"]').type('Demo Ivan Petrov');
        cy.get('#details [name="phone"]').type('0888123456');
        cy.get('#details [name="email"]').type('demo.ivan@example.invalid');
        cy.assertNoBusinessChange(before);
        capture(31, 'CLIENT', 'contact-details-ready', 'Enter the synthetic client name, required phone and optional example.invalid email.',
          'The completed contact form is ready; no new appointment has been created yet.', '#details');
        cy.get('#details button').click();
        cy.location('pathname').should('match', /^\/book\/[a-f0-9-]+\/$/);
        cy.contains('h1', 'You are booked in.').should('be.visible');
        cy.contains('Demo Ivan Petrov').should('be.visible');
        cy.task('db:snapshot').then((after) => {
          expect(after.appointments).to.have.length(3);
          const created = after.appointments.find((row) => row.customer_name === 'Demo Ivan Petrov');
          expect(created).to.include({ barber_id: seed.barbers.alan, service_id: seed.services.cut,
            phone: '0888123456', email: 'demo.ivan@example.invalid', duration_minutes: 30, price: '20.00', cancelled_at: null });
          expect(created.starts_at).to.contain('2026-11-17 07:00:00');
          Object.keys(before).filter((key) => key !== 'appointments').forEach((key) => expect(after[key], key).to.deep.equal(before[key]));
        });
        capture(32, 'CLIENT', 'booking-confirmed', 'Submit the completed booking form.',
          'You are booked in appears with the reservation summary; exactly one new appointment is persisted.');
        cy.get('main .details-panel').then(($panel) => {
          const rect = $panel[0].getBoundingClientRect();
          cy.screenshot('core-client-confirmed', { capture: 'viewport', overwrite: true,
            clip: { x: Math.floor(rect.left), y: Math.floor(rect.top), width: Math.ceil(rect.width), height: 420 } });
        });
      });
    });
  });
});
